cd /tmp/sv-d3383146c62d4a4ead9b600b55d0e966

# The stripped binary is all we have. Let's do a more careful analysis.
# Check which exported functions are nearest to each address and verify with size bounds
python3 << 'PYEOF'
import re

# Read all function symbols
funcs = []
with open('/tmp/funcsyms.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            size = int(parts[1])
            name = parts[2]
            funcs.append((addr, size, name))

funcs.sort()

def lookup(pc):
    addr = int(pc, 16)
    best = None
    for func_addr, func_size, func_name in funcs:
        if func_addr <= addr:
            best = (func_addr, func_size, func_name)
        else:
            break
    if best:
        offset = addr - best[0]
        in_bounds = offset < best[1] if best[1] > 0 else False
        return f"{best[2]}+0x{offset:x}" + ("" if in_bounds else " (outside function bounds, likely internal/static function)")
    return "??"

addresses = {
    "Thread: main (tid: 7020)": [
        ("01", "222098"),
        ("02", "2241ac"),
        ("03", "1abc80"),
        ("04", "16de04"),
    ],
    "Thread: SGen worker (tid: 7046)": [
        ("02", "2f4b20"),
        ("03", "2f4c84"),
    ],
    "Thread: Finalizer (tid: 7048)": [
        ("02", "2c1a40"),
    ],
}

for thread, frames in addresses.items():
    print(f"\n=== {thread} ===")
    for fnum, pc in frames:
        sym = lookup(pc)
        print(f"  #{fnum} pc 0x{pc}  {sym}")
